def _coerce_dict_crawl_config(value: dict[str, Any]) -> CrawlConfig:
    """Coerce a dict into CrawlConfig, converting nested types in-place."""
    _struct_coercions = {
        "content": _to_rust_content_config,
        "browser": _to_rust_browser_config,
        "proxy": _to_rust_proxy_config,
        "ssrf": _to_rust_ssrf_policy,
    }
    for _k, _fn in _struct_coercions.items():
        if _k in value and value[_k] is not None:
            value[_k] = _fn(value[_k])
    _enum_coercions = {
        "crawl_strategy": _rust.CrawlStrategyKind,
        "content_filter": _rust.ContentFilterKind,
        "document_content_encoding": _rust.DocumentContentEncoding,
    }
    for _k, _cls in _enum_coercions.items():
        if _k in value and value[_k] is not None:
            value[_k] = _coerce_enum(_cls, value[_k])
    _data_enum_coercions = {
        "auth": _rust.AuthConfig,
    }
    for _k, _data_cls in _data_enum_coercions.items():
        if _k in value and value[_k] is not None and not isinstance(value[_k], _data_cls):
            value[_k] = _data_cls(value[_k])
    return CrawlConfig(**value)


