def doctor(config: ExtractionConfig | None = None) -> DoctorReport:
    """Probe the backends and settings in `config` and report what will actually execute on this."""
    _rust_config = _to_rust_extraction_config(config) if config is not None else _rust.ExtractionConfig()
    return _from_native_doctor_report(_rust.doctor(config=_rust_config))


async def extract(
    input: ExtractInput | None = None,  # noqa: A002
    config: ExtractionConfig | None = None,
) -> ExtractionResult:
    """Extract content from a single bytes or URI input."""
    _rust_input = _to_rust_extract_input(input) if input is not None else _rust.ExtractInput()
    _rust_config = _to_rust_extraction_config(config) if config is not None else _rust.ExtractionConfig()
    return await _rust.extract(input=_rust_input, config=_rust_config)


async def extract_batch(
    inputs: list[ExtractInput],
    config: ExtractionConfig | None = None,
) -> ExtractionResult:
    """Extract content from multiple bytes or URI inputs."""
    _rust_inputs = [_to_rust_extract_input(__item) for __item in inputs]

    _rust_config = _to_rust_extraction_config(config) if config is not None else _rust.ExtractionConfig()
    return await _rust.extract_batch(inputs=_rust_inputs, config=_rust_config)


async def extract_with_external_redaction(
    input: ExtractInput,  # noqa: A002
    config: ExtractionConfig,
    findings_json: str,
    offset_encoding: str | None = None,
    max_findings: int | None = None,
) -> ExtractionResult:
    """Extract one bytes input and redact a JSON array or JSON Lines payload from an external in."""
    _rust_input = _to_rust_extract_input(input)

    if _rust_input is None:
        _rust_input = _rust.ExtractInput()
    _rust_config = _to_rust_extraction_config(config)

    if _rust_config is None:
        _rust_config = _rust.ExtractionConfig()
    return await _rust.extract_with_external_redaction(
        input=_rust_input,
        config=_rust_config,
        findings_json=findings_json,
        offset_encoding=offset_encoding,
        max_findings=max_findings,
    )


