async def redact_external(
    document: ExtractedDocument,
    config: RedactionConfig,
    findings_json: str,
    offset_encoding: str | None = None,
    max_findings: int | None = None,
) -> ExtractedDocument:
    """Redact an owned document using a JSON array or JSON Lines payload from an external inspec."""
    _rust_document = _to_rust_extracted_document(document)

    if _rust_document is None:
        _rust_document = _rust.ExtractedDocument()
    _rust_config = _to_rust_redaction_config(config)

    if _rust_config is None:
        _rust_config = _rust.RedactionConfig()
    return await _rust.redact_external(
        document=_rust_document,
        config=_rust_config,
        findings_json=findings_json,
        offset_encoding=offset_encoding,
        max_findings=max_findings,
    )


